+const { Queue } = require("bullmq");
+const IORedis = require("ioredis");
+
+const redisUrl = "redis://redis:6379";
+const connection = new IORedis(redisUrl, { maxRetriesPerRequest: null });
+const jobs = new Queue("jobs", { connection });
+const deadLetters = new Queue("jobs-dlq", { connection });
+
+const JOB_OPTIONS = { attempts: 3, backoff: { type: "fixed", delay: 200 }, removeOnComplete: 5000 };
+
+async function replayDLQ() {
+  try {
+    const dlqJobs = await deadLetters.getJobs(["failed"], 0, -1);
+    console.log(`Found ${dlqJobs.length} failed jobs in DLQ`);
+    
+    for (const dlqJob of dlqJobs) {
+      console.log(`Replaying job: ${dlqJob.name} (${dlqJob.id})`);
+      const { error, ...originalData } = dlqJob.data;
+      await jobs.add(dlqJob.name, originalData, { ...JOB_OPTIONS, jobId: dlqJob.id });
+      console.log(`Enqueued job: ${dlqJob.id}`);
+    }
+    
+    console.log("Done replaying DLQ");
+  } finally {
+    await connection.quit();
+  }
+}
+
+replayDLQ().catch(err => {
+  console.error("Error:", err);
+  process.exit(1);
+});
