+const { Queue } = require("bullmq");
+const IORedis = require("ioredis");
+
+const redisUrl = "redis://redis:6379";
+const connection = new IORedis(redisUrl, { maxRetriesPerRequest: null });
+const jobs = new Queue("jobs", { connection });
+const deadLetters = new Queue("jobs-dlq", { connection });
+
+const JOB_OPTIONS = { attempts: 3, backoff: { type: "fixed", delay: 200 }, removeOnComplete: 5000 };
+
+const JPY_JOB_IDS = [
+  "2d6d6163-b9e1-4b19-a978-f87f7fa2ad7d",
+  "f201db53-be7e-4a38-b857-04ed1165bdea",
+  "175cc081-bcd9-4d5f-8d28-b99d4b8bac39",
+  "8527256a-f248-46b0-a745-adeaaeb4c657",
+  "2172e6a1-d7e3-46a4-94ee-23b8279a9f2b",
+  "ca070bc9-15f6-451c-93f6-506ed1628479",
+  "7acfd597-4cef-44bd-be0e-30bd6aa51844",
+  "289ec37f-54d4-4504-a989-a831fae8879e",
+  "b7a7c492-0350-449c-99e1-f8f3bad2f212",
+  "db815555-06a2-467d-9785-0c3d8a930c18",
+];
+
+async function replayJPYJobs() {
+  try {
+    console.log(`Attempting to replay ${JPY_JOB_IDS.length} JPY jobs`);
+    
+    for (const jobId of JPY_JOB_IDS) {
+      try {
+        // Try to get from DLQ first
+        let jobData = null;
+        const dlqJobs = await deadLetters.getJobs(["failed"], 0, -1);
+        const dlqJob = dlqJobs.find(j => j.id === jobId);
+        
+        if (dlqJob) {
+          console.log(`Found job in DLQ: ${jobId}`);
+          const { error, ...originalData } = dlqJob.data;
+          jobData = originalData;
+        } else {
+          // Try to reconstruct from Redis directly
+          const data = await connection.hget(`bull:jobs-dlq:${jobId}`, "data");
+          if (data) {
+            const parsed = JSON.parse(data);
+            const { error, ...originalData } = parsed;
+            jobData = originalData;
+            console.log(`Reconstructed job from Redis: ${jobId}`);
+          }
+        }
+        
+        if (jobData) {
+          await jobs.add("order", jobData, { ...JOB_OPTIONS, jobId: jobId });
+          console.log(`Re-enqueued job: ${jobId}`);
+        } else {
+          console.log(`Could not find data for job: ${jobId}`);
+        }
+      } catch (err) {
+        console.error(`Error processing job ${jobId}:`, err.message);
+      }
+    }
+    
+    console.log("Done replaying JPY jobs");
+  } finally {
+    await connection.quit();
+  }
+}
+
+replayJPYJobs().catch(err => {
+  console.error("Error:", err);
+  process.exit(1);
+});
