const IORedis = require(\"ioredis\");

const redis = new IORedis(process.env.REDIS_URL || \"redis://localhost:6379\");

async function recover() {
  try {
    // Get all job IDs from the DLQ wait list
    const jobIds = await redis.lrange(\"bull:jobs-dlq:wait\", 0, -1);
    console.log("'`Found ${jobIds.length} jobs in DLQ`);

    for (const jobId of jobIds) {
      // Fetch the job data from DLQ
      const jobData = await redis.hgetall(`bull:jobs-dlq:${jobId}`);
      if (!jobData || !jobData.data) {
        console.log(`Skipping ${jobId} - no data found`);
        continue;
      }

      const data = JSON.parse(jobData.data);
      const name = jobData.name || "notification";

      // Remove error field added when moving to DLQ
      delete data.error;

      // Create new job in main queue
      const jobStr = JSON.stringify({
        name,
        data,
        opts: {
          jobId,
          attempts: 3,
          backoff: { type: "fixed", delay: 200 },
          removeOnComplete: 5000,
        },
      });

      // Add to main jobs queue
      await redis.hset(`bull:jobs:${jobId}`, "data", JSON.stringify(data));
      await redis.hset(`bull:jobs:${jobId}`, "name", name);
      await redis.hset(`bull:jobs:${jobId}`, "opts", JSON.stringify({
        jobId,
        attempts: 3,
        backoff: { type: "fixed", delay: 200 },
        removeOnComplete: 5000,
      }));

      // Add to wait list
      await redis.rpush("bull:jobs:wait", jobId);

      console.log(`Recovered job ${jobId}`);
    }

    console.log("Recovery complete!");
    process.exit(0);
  } catch (err) {
    console.error("Error:", err);
    process.exit(1);
  }
}

recover();
